/** Resolve the rev-530 map-square id containing a tile. */
export function regionIdOf(tile: Pick<TileCoord, 'x' | 'z'>): number;
/** Compatibility overload for existing coordinate callers. */
export function regionIdOf(x: number, z: number): number;
export function regionIdOf(tileOrX: Pick<TileCoord, 'x' | 'z'> | number, z?: number): number {
  return typeof tileOrX === 'number'
    ? coordinateRegionIdOf(tileOrX, z as number)
    : coordinateRegionIdOf(tileOrX.x, tileOrX.z);
}

/** Resolve a stable named region, falling back to `region <id>`. */
export function regionNameOf(tile: Pick<TileCoord, 'x' | 'z'>): string {
  const regionId = regionIdOf(tile);
  return REGION_NAMES[regionId] ?? `region ${regionId}`;
}
